WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_doc_format'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '公文格式规范', 'kp-sl-doc-format', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "公文格式规范"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心规则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "公文得分的第一步是形式正确。格式不对，内容再好也要扣分。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、完整五要素"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "标题：居中书写，不能加书名号。常规结构为“发文机关 + 关于 + 事由 + 的 + 文种”（如：XX县人民政府关于表彰见义勇为先进个人的决定）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "称谓（主送机关）：顶格写，加冒号。如“各乡镇人民政府：”、“各位村民朋友：”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "正文：另起一行，空两格。这是内容的核心。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "落款（发文机关/人）：正文右下方。如“XX县政府办公室”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "成文日期：落款的正下方。如“202X年X月X日”。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、不完整格式（提纲/要点）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "提纲与正文的区别：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果题目明确要求写“讲话提纲”、“报道要点”，通常只需要写【标题 + 正文】，不需要称谓和落款日期！乱加落款反而显得你不懂规矩。"}]}]}]}$$ AS jsonb), NULL, '公文格式规范的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "公文写作", "格式规范"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_doc_format", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
